import{_ as p,a0 as n,w as o,s as u,I as i,x as l,a1 as a,A as s,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"使用 FileZilla 以图形界面连接 SFTP 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 FileZilla 以图形界面连接 SFTP 服务器 | LCTT (202203) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 FileZilla 以图形界面连接 SFTP 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 FileZilla 以图形界面连接 SFTP 服务器 | LCTT (202203) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI","title":"使用 FileZilla 以图形界面连接 SFTP 服务器","tag":"202203","desc":""},"relativePath":"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI.md","filePath":"[post].md"}'),f={name:"202203/20220307 Using FileZilla for Connecting to SFTP Server Via GUI.md"};function m(d,t,b,g,T,F){const e=n("Link");return o(),u("div",null,[t[25]||(t[25]=i("h1",{id:"使用-filezilla-以图形界面连接-sftp-服务器",tabindex:"-1"},[l("使用 FileZilla 以图形界面连接 SFTP 服务器 "),i("a",{class:"header-anchor",href:"#使用-filezilla-以图形界面连接-sftp-服务器","aria-label":"Permalink to “使用 FileZilla 以图形界面连接 SFTP 服务器”"},"​")],-1)),t[26]||(t[26]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202203/29/164256iljy9w3n053qv28x.jpg",alt:""})],-1)),i("p",null,[t[1]||(t[1]=l("如果你问那些极客系统管理员，他们会肯定的说使用 ",-1)),a(e,{href:"https://linuxhandbook.com/transfer-files-ssh/"},{default:s(()=>[...t[0]||(t[0]=[l("rsync 或者 scp 命令在远程服务器和本地系统之间传输文件",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[27]||(t[27]=i("p",null,"然而，这些都是命令行方式，并不是每个人都能用起来感到舒适。",-1)),t[28]||(t[28]=i("p",null,"谢天谢地的是，有一些图形化工具能够让你从远程服务器来传输文件。",-1)),i("p",null,[a(e,{href:"https://filezilla-project.org/"},{default:s(()=>[...t[3]||(t[3]=[l("FileZilla",-1)])]),_:1}),t[4]||(t[4]=l(" 是一个流行的、跨平台的传输文件为目的开源软件。它支持使用通过 TLS 或者 SSL 加密的 FTP 协议（FTPS），也支持借助 SSH 的 FTP 协议，以及旧的 FTP 协议。",-1))]),t[29]||(t[29]=r('<p>让我展示怎样在 Linux 上安装 FileZilla 然后用它来文件传输。</p><p>那么，让我们开始吧！</p><h3 id="在-ubuntu-和其他-linux-发行版上安装-filezilla" tabindex="-1">在 Ubuntu 和其他 Linux 发行版上安装 FileZilla <a class="header-anchor" href="#在-ubuntu-和其他-linux-发行版上安装-filezilla" aria-label="Permalink to “在 Ubuntu 和其他 Linux 发行版上安装 FileZilla”">​</a></h3><p>你可以使用源码来安装，但是还是建议使用你的发行版提供的软件包。因为它是一个热门软件，它应该在许多 Linux 发行版（即便不是全部）的软件仓库中可用。请使用你的发行版的软件中心和包管理器来安装。</p><p>在 Ubuntu 上，你可以从软件中心来安装它：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/filezilla-ubuntu-software-center.png?resize=751%2C382&amp;ssl=1" alt="FileZilla is available in the Ubuntu Software Center"></p><p>你也可以使用命令行的方式来安装它：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install filezilla</span></span></code></pre></div>',8)),i("p",null,[t[7]||(t[7]=l("如果你看到 ",-1)),a(e,{href:"https://itsfoss.com/unable-to-locate-package-error-ubuntu/"},{default:s(()=>[...t[5]||(t[5]=[l("软件包不存在的错误",-1)])]),_:1}),t[8]||(t[8]=l("，你应该 ",-1)),a(e,{href:"https://itsfoss.com/ubuntu-repositories/"},{default:s(()=>[...t[6]||(t[6]=[l("开启 Universe 仓库",-1)])]),_:1}),t[9]||(t[9]=l("。",-1))]),t[30]||(t[30]=r('<p>一旦安装成功，打开菜单（通过按 <code>Super</code> 键），键入 “FileZilla”来启动它。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/03/filezilla-ubuntu.png?resize=763%2C224&amp;ssl=1" alt="Start FileZilla from the system menu"></p><h3 id="使用-filezilla" tabindex="-1">使用 FileZilla <a class="header-anchor" href="#使用-filezilla" aria-label="Permalink to “使用 FileZilla”">​</a></h3><p>第一次使用 FileZilla 时，你将会看到如下图所示的一个界面：</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/01_filezilla.webp?resize=800%2C431&amp;ssl=1" alt="Screenshot of FileZilla running"></p><p>左边窗口显示来自你本地系统的文件和目录。右边窗口显示目前是空的。当你连接到远程服务器时，来自你的远程系统的文件会显示在这里。</p><p>在我向你展示之前，让我分享一下关于理解 FileZilla 图形界面重要方面的一些细节。</p><h4 id="了解-filezilla-图形界面" tabindex="-1">了解 FileZilla 图形界面 <a class="header-anchor" href="#了解-filezilla-图形界面" aria-label="Permalink to “了解 FileZilla 图形界面”">​</a></h4><p>下图总体上给你展示了 FileZilla 窗口布局的不同部分。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/02_filezilla_layout.webp?resize=800%2C504&amp;ssl=1" alt="FileZilla Window Layout | image credit"></p><p>图形界面由 6 个不同的区域/窗口来组成。让我简短的给你解释一下：</p><p><strong>1、工具栏</strong>：它有许多选项，如打开站点管理器、刷新本地和远程目录文件和文件列表、开始处理当前的文件传输队列、停止正在传输的任务并取消队列中的文件，等等。</p><p><strong>2、快速连接栏</strong>：顾名思义，它允许你快速连接到一个远程站点，除了主机名、用户名、密码和端口之外，不需要指定更多细节。</p><p><strong>3、消息日志</strong>：它显示了一个日志，不论你连接成功与否。错误消息标记为红色，正常消息为白色，命令是蓝色。</p><p><strong>4 &amp; 5、本地窗口和远程窗口</strong>：这两个窗口非常相似，除了本地窗口显示本地目录内容，并且有用来上传文件的上下文菜单；而远程窗口显示的是远程目录的内容，并有从远程目录下载到本地文件的选项。</p><p><strong>6、传输队列</strong>：最后，传输队列窗口显示正在传输的项目的状态和它们的传输速度，以及队列中的文件和传输历史（仅限当前实例）。</p><h4 id="使用-filezilla-连接到-sftp-服务器" tabindex="-1">使用 FileZilla 连接到 SFTP 服务器 <a class="header-anchor" href="#使用-filezilla-连接到-sftp-服务器" aria-label="Permalink to “使用 FileZilla 连接到 SFTP 服务器”">​</a></h4><p>你需要知道远程服务器的用户名、密码和 IP 地址。远程服务器也应该被设置成能够接受以这些信息进行的连接。你还需要在目标文件夹有正确的权限设置。</p><p>要新增一个 SFTP 连接，你需要打开站点管理器。有两种方式可以打开它。</p><p>在菜单栏上的“<ruby>文件<rt>Files</rt></ruby>”菜单选项下有一个“<ruby>站点管理器<rt>Site Manager</rt></ruby>”。或者，你可以直接点击工具栏上的“站点管理器”图标。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/03_site_manager_annotated.webp?resize=386%2C170&amp;ssl=1" alt="the Site Manager button on the toolbar"></p><p>一旦站点管理器对话框弹出，点击“<ruby>新站点<rt>New site</rt></ruby>”按钮，并（可选地）重命名添加到条目中的新站点。我叫我的站点为“test8”。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/04_site_manager.webp?resize=800%2C577&amp;ssl=1" alt="screenshot of the Site Manager"></p><p>在右侧的“<ruby>常规<rt>General</rt></ruby>”标签下，确保所使用的协议与服务器管理员为你设置的相一致。在我的例子中，我设置了一个 SFTP 服务器（<ruby>借助 SSH 通道的 FTP<rt>FTP over SSH</rt></ruby>），因此我选择了“<ruby>SFTP - SSH 文件传输协议<rt>SFTP – SSH File Transfer Protocol</rt></ruby>”。</p><p>下一个字段填写远程服务器的 IP 地址。</p><p>如果你没有设置“<ruby>端口号<rt>Port</rt></ruby>”，FileZilla 将假定要使用的端口号为缺省的 SSH 协议的 22 端口。</p><p>“<ruby>登录类型<rt>Logon Type</rt></ruby>”下拉列表有几个选项。在“<ruby>常规<rt>Normal</rt></ruby>”登录方式下，你只需要提供用户名和密码。</p><p>如果你设置了一对公钥和私钥来验证你的 SSH 用户连接，那么可以使用“<ruby>密钥文件授权<rt>Key file authentication</rt></ruby>”方式。</p><p>一旦你为远程服务器和认证填写了所有适当的细节，就可以点击底部的“<ruby>连接<rt>Connect</rt></ruby>”按钮连接到站点。别担心，你刚刚建立连接的新站点将会按“登录类型”保存起来。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/05_successful_connection.webp?resize=800%2C431&amp;ssl=1" alt="Remote pane being populated after a successful connection"></p><p>如果你看到一个 “连接到 &lt;主机 IP 地址&gt;” 的状态消息，并且最近的状态消息是 “目录列表 &quot;/&quot; 显示成功”，说明你已经成功的连接到了远程的 SFTP 服务器（使用 SSH 协议的 FTP）。</p><p>另一个 SFTP 连接成功的标志是，当连接成功建立的时候，远程目录窗口有了很多消息。</p><h4 id="发送文件到远程系统" tabindex="-1">发送文件到远程系统 <a class="header-anchor" href="#发送文件到远程系统" aria-label="Permalink to “发送文件到远程系统”">​</a></h4><p>你必须 <strong>确保你位于要传输文件的目录里</strong>。传输文件非常简单，只需<strong>双击文件</strong>，无需指定指定目标位置。</p><p>如果你在左边窗口双击了一个文件，它立即传输到右边科技的目录里（或者有传输任务的话，加到队列中）。</p><p>同样，从右边窗口到左边窗口也是一样双击，即从远程服务器到本地。<strong>这就是为什么本地和远程系统都要在正确的位置是非常重要的原因</strong>。</p><p>此外，你也可以鼠标右击文件上传它们（或者加它们到上传队列）。目标位置总是 FileZilla 界面中显示的目录。</p><p><img src="https://i0.wp.com/itsfoss.com/wp-content/uploads/2022/01/07_transfer_pane_populated-1.webp?resize=800%2C431&amp;ssl=1" alt="Transfer queue pane showing the local file name, remote destination, transfer speed and an ETA"></p><p>除了方便和快捷方面，这两种上传的文件方式没有什么不同。</p><h4 id="下载远程系统中的文件" tabindex="-1">下载远程系统中的文件 <a class="header-anchor" href="#下载远程系统中的文件" aria-label="Permalink to “下载远程系统中的文件”">​</a></h4><p>像上传文件一样，当从远程服务器传输文件到本地时也有两种方式，但不是“上传”而是“下载”。</p><p>下载的文件将放在本地目录窗口中，也就是你当前打开的本地窗口。</p><p>你将会注意到除了发送方和接收方不同之外，下载和上传文件的行为是一样的。除非连接数受到限制，否则文件传输将是并行进行的。</p><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>厉害！有了这些基础知识，你应该能够在你的计算机和服务器之间传输文件。我希望你能够学到一些新东西 : )</p><p>如果你感到这些对你有帮助，随意在评论部分留下你的问题、建议或简单的一句 “thank you”。</p><hr>',47)),i("p",null,[t[11]||(t[11]=l("via: ",-1)),a(e,{href:"https://itsfoss.com/filezilla-ubuntu/"},{default:s(()=>[...t[10]||(t[10]=[l("https://itsfoss.com/filezilla-ubuntu/",-1)])]),_:1})]),i("p",null,[t[16]||(t[16]=l("作者：",-1)),a(e,{href:"https://itsfoss.com/author/pratham/"},{default:s(()=>[...t[12]||(t[12]=[l("Pratham Patel",-1)])]),_:1}),t[17]||(t[17]=l(" 选题：",-1)),a(e,{href:"https://github.com/lujun9972"},{default:s(()=>[...t[13]||(t[13]=[l("lujun9972",-1)])]),_:1}),t[18]||(t[18]=l(" 译者：",-1)),a(e,{href:"https://github.com/hwlife"},{default:s(()=>[...t[14]||(t[14]=[l("hwlife",-1)])]),_:1}),t[19]||(t[19]=l(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[15]||(t[15]=[l("wxy",-1)])]),_:1})]),i("p",null,[t[22]||(t[22]=l("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[20]||(t[20]=[l("LCTT",-1)])]),_:1}),t[23]||(t[23]=l(" 原创编译，",-1)),a(e,{href:"https://linux.cn/"},{default:s(()=>[...t[21]||(t[21]=[l("Linux中国",-1)])]),_:1}),t[24]||(t[24]=l(" 荣誉推出",-1))])])}const y=p(f,[["render",m]]);export{P as __pageData,y as default};
